from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock):
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self._data = OrderedDict()  # key -> (value, inserted_at); end = MRU

    def _expired(self, ts) -> bool:
        # An entry is valid for [inserted_at, inserted_at + ttl); it expires at exactly ttl.
        return self.clock() - ts >= self.ttl

    def _purge(self):
        dead = [k for k, (_, ts) in self._data.items() if self._expired(ts)]
        for k in dead:
            del self._data[k]

    def put(self, key, value) -> None:
        if key in self._data:
            del self._data[key]
        else:
            self._purge()
            while self._data and len(self._data) >= self.capacity:
                self._data.popitem(last=False)
        self._data[key] = (value, self.clock())

    def get(self, key, default=None):
        if key not in self._data:
            return default
        value, ts = self._data[key]
        if self._expired(ts):
            del self._data[key]
            return default
        self._data.move_to_end(key)
        return value

    def __len__(self) -> int:
        self._purge()
        return len(self._data)
